for index, row in enumerate(_ROWS, 1):
    label, title, group, priority, hypothesis, text, questions, owner, action, prevention = row
    PLAYBOOKS.append({"id": f"KB-{index:02d}", "label": label, "title": title,
                      "group": group, "priority": priority, "hypothesis": hypothesis,
                      "text": text, "questions": questions, "owner": owner,
                      "action": action, "prevention": prevention,
                      "source": "Authored demo investigation playbook",
                      "version": "1.0", "status": "Demonstration guidance"})
